    # different-color bars on the same row as separate adjacent runs.
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v]
        if len(cols) < 2:
            continue
        runs = []
        start = prev = cols[0]
        color = row[start]
        for c in cols[1:]:
            if c == prev + 1 and row[c] == color:
                prev = c
            else:
                runs.append((start, prev, color))
                start = prev = c
                color = row[c]
        runs.append((start, prev, color))
        horizontal_rows.append(r)
        row_runs[r] = runs
        for i, (left, right, color) in enumerate(runs):
            end = runs[i + 1][0] - 1 if i + 1 < len(runs) else (max(cols) if len(runs) == 1 else right)
            for c in range(left, end + 1):
                out[r][c] = color

    # Vertical traces are the one-cell holes inside horizontal bars. Each hole
    # receives the color of the neighboring bar segment and extends to the
    # next horizontal row (or edge). In these patterns holes identify distinct
    # columns; gaps of more than one cell are not vertical traces.
    for r in horizontal_rows:
        runs = row_runs[r]
        for left, right in zip(runs, runs[1:]):
            gap = left[1] + 1
            if runs[runs.index(right)][0] - gap != 1:
                continue
