            above = max((rr for rr in horizontal_rows if rr < r), default=-1)
            for rr in range(r - 1, above, -1):
                out[rr][gap] = color

    # Repeated isolated vertical lines extend through the adjacent gap between
    # their segment and the nearest horizontal bar, adopting the bar color at
    # that column.
    horizontal_set = set(horizontal_rows)
