 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bars = []
    marker_rows = set()

    # Complete horizontal bars. Rows with long spans are the horizontal bars;
    # their color runs define boundaries when bars of different colors touch.
    for r, row in enumerate(grid):
        cols = [c for c, value in enumerate(row) if value]
        if len(cols) < 5:
            continue
        runs = []
        start = previous = cols[0]
        color = row[start]
        for c in cols[1:]:
            if c == previous + 1 and row[c] == color:
                previous = c
            else:
                runs.append((start, previous, color))
                start = previous = c
                color = row[c]
        runs.append((start, previous, color))
        bars.append((r, runs))
        for i, (left, right, color) in enumerate(runs):
            end = runs[i + 1][0] - 1 if i + 1 < len(runs) else (max(cols) if len(runs) == 1 else right)
            for c in range(left, end + 1):
                out[r][c] = color

    bar_rows = {r for r, _ in bars}
    gap_events = {}
    for r, runs in bars:
        for left, right in zip(runs, runs[1:]):
            gap = left[1] + 1
            if runs[runs.index(right)][0] - gap == 1:
                color = left[2] if left[2] == right[2] else right[2]
                gap_events.setdefault(gap, []).append((r, color))

    # Vertical line columns are identified by aligned gaps in multiple bars.
    # The top region uses its top bar's color; between bars the lower bar's
    # color continues upward to the preceding horizontal level.
    for c, events in gap_events.items():
        events.sort()
        first_row, first_color = events[0]
        for rr in range(first_row - 1, -1, -1):
            if grid[rr][c] == 0:
                out[rr][c] = first_color
        for (_, _), (lower_row, lower_color) in zip(events, events[1:]):
            upper_row = events[events.index((lower_row, lower_color)) - 1][0]
            for rr in range(upper_row + 1, lower_row):
                if grid[rr][c] == 0:
                    out[rr][c] = lower_color

    # Sparse marker pixels below the final bar continue vertically to the grid
    # bottom. Each marker column is extended using the marker's own color.
    last_bar = max(bar_rows) if bar_rows else -1
    for c in range(w):
        marks = [(r, grid[r][c]) for r in range(last_bar + 1, h) if grid[r][c]]
        if not marks:
            continue
        color = marks[0][1]
        for rr in range(last_bar + 1, h):
            if grid[rr][c] == 0:
                out[rr][c] = color

    return out
