 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bars = []

    # Find long horizontal bars and fill their broken spans.
    for r, row in enumerate(grid):
        cols = [c for c, value in enumerate(row) if value != 0]
        if len(cols) < 5:
            continue
        colors = set(row[c] for c in cols)
        if len(colors) == 1:
            color = row[cols[0]]
            for c in range(min(cols), max(cols) + 1):
                out[r][c] = color
            bars.append((r, min(cols), max(cols), color))
            continue

        # When multiple bars share a row, each color occupies the interval
        # from its first observed cell to the start of the next color's run.
        runs = []
        start = previous = cols[0]
        color = row[start]
        for c in cols[1:]:
            if c == previous + 1 and row[c] == color:
                previous = c
            else:
                runs.append((start, previous, color))
                start = previous = c
                color = row[c]
        runs.append((start, previous, color))
        for i, (left, right, color) in enumerate(runs):
            end = runs[i + 1][0] - 1 if i + 1 < len(runs) else max(cols)
            for c in range(left, end + 1):
                out[r][c] = color
        bars.append((r, min(cols), max(cols), None))

    # The isolated cells below the bars identify vertical line columns. Along
    # each such column, every horizontal bar paints the interval above itself;
    # below the last bar, continue the color of the lower marker.
    last_bar_row = max((bar[0] for bar in bars), default=-1)
    track_columns = sorted({c for r in range(last_bar_row + 1, h)
                            for c in range(w) if grid[r][c] != 0})

    for c in track_columns:
        contributing = []
        for r, left, right, _ in bars:
            if left <= c <= right and out[r][c] != 0:
                contributing.append((r, out[r][c]))
        contributing.sort()
        if not contributing:
            continue

        # Each horizontal bar's color fills upward to the previous bar on this
        # track, or to the top edge for the first one.
        for i, (r, color) in enumerate(contributing):
            upper = contributing[i - 1][0] if i > 0 else -1
            for rr in range(r, upper, -1):
                out[rr][c] = color

        # Lower marker segments provide the color below the last bar.
        marker_color = grid[last_bar_row + 1][c] if last_bar_row + 1 < h and grid[last_bar_row + 1][c] else None
        if marker_color is None:
            marker_color = next(grid[r][c] for r in range(last_bar_row + 1, h) if grid[r][c])
        for rr in range(last_bar_row + 1, h):
            out[rr][c] = marker_color

    return out
