 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bars = []

    # Horizontal bars are rows containing multiple separated fragments. Fill
    # their missing spans; if two colors share a row, keep their boundary.
    for r, row in enumerate(grid):
        cols = [c for c, value in enumerate(row) if value]
        if len(cols) < 2:
            continue
        runs = []
        start = previous = cols[0]
        color = row[start]
        for c in cols[1:]:
            if c == previous + 1 and row[c] == color:
                previous = c
            else:
                runs.append((start, previous, color))
                start = previous = c
                color = row[c]
        runs.append((start, previous, color))
        bars.append((r, runs))
        for i, (left, right, color) in enumerate(runs):
            if len(runs) == 1:
                end = max(cols)
            elif i + 1 < len(runs):
                end = runs[i + 1][0] - 1
            else:
                end = right
            for c in range(left, end + 1):
                out[r][c] = color

    # Between horizontal bars, extend the vertical stroke whose color matches
    # the bar pattern. Each stroke is identified by the one-cell gap in a bar;
