 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Long, fragmented rows are the horizontal bars. Fill only single-cell
    # holes bracketed by the same color, and record each hole as a vertical ray.
    bar_rows = []
    gaps = []
    for r, row in enumerate(grid):
        cols = [c for c, value in enumerate(row) if value != 0]
        if len(cols) < 5:
            continue
        bar_rows.append(r)
        for c in range(1, w - 1):
            if row[c] == 0 and row[c - 1] != 0 and row[c - 1] == row[c + 1]:
                color = row[c - 1]
                out[r][c] = color
                gaps.append((r, c, color))

    # Each broken bar sends its gap color upward. Existing cells (including
    # other completed bars/gaps) stop a ray and retain their own color.
    for r, c, color in sorted(gaps, reverse=True):
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color

    # Sparse colored markers beneath the lowest bar are vertical strokes.
    # Extend each upward through empty cells until it meets an existing bar or
    # vertical ray, preserving all original marker pixels and their colors.
    last_bar = max(bar_rows) if bar_rows else -1
    for c in range(w):
        marks = [r for r in range(last_bar + 1, h) if grid[r][c] != 0]
        if not marks:
            continue
        top = min(marks)
        color = grid[top][c]
        for rr in range(top, h):
            if out[rr][c] == 0:
                out[rr][c] = color
        for rr in range(top - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color

    return out
